def safe_int(value, default=0):
    try:
        return int(str(value).strip())
    except (TypeError, ValueError):
        return default


# Environment variable ko priority milegi; warna direct value use hogi.
BOT_TOKEN = os.getenv("BOT_TOKEN", "").strip() or DIRECT_BOT_TOKEN.strip()
