def ensure_welcome_image():
    """Create the embedded welcome image on first run."""
    image_path = Path(WELCOME_IMAGE_FILE)

    if not image_path.exists():
        image_path.write_bytes(
            base64.b64decode(WELCOME_IMAGE_BASE64)
        )

    return image_path


