def now_text():
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def open_database():
    connection = sqlite3.connect(
        DATABASE_FILE,
        check_same_thread=False,
    )
    connection.row_factory = sqlite3.Row
    return connection


def initialize_database():
    db = open_database()

    db.executescript(
        """
        CREATE TABLE IF NOT EXISTS admins (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            role TEXT NOT NULL DEFAULT 'superadmin',
            is_active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS bot_users (
            telegram_id INTEGER PRIMARY KEY,
            first_name TEXT,
            username TEXT,
            last_action TEXT,
            joined_at TEXT,
            updated_at TEXT
        );

        CREATE TABLE IF NOT EXISTS settings (
            setting_key TEXT PRIMARY KEY,
            setting_value TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS custom_buttons (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            button_text TEXT NOT NULL,
            button_type TEXT NOT NULL,
            button_value TEXT NOT NULL,
            sort_order INTEGER NOT NULL DEFAULT 100,
            is_active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS applications (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_code TEXT UNIQUE,
            telegram_id INTEGER NOT NULL,
            customer_name TEXT,
            telegram_username TEXT,
            service_type TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'Pending',
            admin_note TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS activity_logs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            admin_username TEXT,
            action TEXT NOT NULL,
            created_at TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS conversations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            telegram_id INTEGER NOT NULL,
            sender_type TEXT NOT NULL,
            message_text TEXT NOT NULL,
            is_read INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );
        """
    )

    admin = db.execute(
        "SELECT id FROM admins WHERE username = ?",
        (ADMIN_USERNAME,),
    ).fetchone()

    if admin is None:
        db.execute(
            """
            INSERT INTO admins
            (username, password_hash, role, is_active, created_at)
            VALUES (?, ?, 'superadmin', 1, ?)
            """,
            (
                ADMIN_USERNAME,
                generate_password_hash(ADMIN_PASSWORD),
                now_text(),
            ),
        )

    # ---------------------------------------------------------
    # DATABASE MIGRATION
    # Purani database file me naye columns automatically add karein.
    # CREATE TABLE IF NOT EXISTS existing table ko update nahi karta,
    # isliye bina migration ke application create karte waqt error aa sakta hai.
    # ---------------------------------------------------------
    def ensure_column(table_name, column_name, column_sql):
        existing_columns = {
            row["name"]
            for row in db.execute(f"PRAGMA table_info({table_name})").fetchall()
        }
        if column_name not in existing_columns:
            db.execute(
                f"ALTER TABLE {table_name} ADD COLUMN {column_name} {column_sql}"
            )

    ensure_column("applications", "application_code", "TEXT")
    ensure_column("applications", "telegram_id", "INTEGER NOT NULL DEFAULT 0")
    ensure_column("applications", "customer_name", "TEXT")
    ensure_column("applications", "telegram_username", "TEXT")
    ensure_column("applications", "service_type", "TEXT NOT NULL DEFAULT 'Business Wallet'")
    ensure_column("applications", "status", "TEXT NOT NULL DEFAULT 'Pending'")
    ensure_column("applications", "admin_note", "TEXT")
    ensure_column("applications", "created_at", "TEXT NOT NULL DEFAULT ''")
    ensure_column("applications", "updated_at", "TEXT NOT NULL DEFAULT ''")

    ensure_column("bot_users", "first_name", "TEXT")
    ensure_column("bot_users", "username", "TEXT")
    ensure_column("bot_users", "last_action", "TEXT")
    ensure_column("bot_users", "joined_at", "TEXT")
    ensure_column("bot_users", "updated_at", "TEXT")

    # Existing records ko safe values dein.
    db.execute(
        "UPDATE applications SET updated_at = created_at "
        "WHERE updated_at IS NULL OR updated_at = ''"
    )

    defaults = {
        "welcome_title": "Welcome to India Business Wallets",
        "google_pay_charge": "1500",
        "bharatpe_charge": "800",
        "support_email": "IndiaBusinessWallets@gmail.com",
        "support_whatsapp": "https://wa.me/message/OPWOWQW4VLJUB1",
        "official_channel": "https://t.me/IndiaBusinessWallets",
        "support_message": (
            "Business Wallet opening ya kisi bhi jankari ke liye "
            "neeche diye gaye button se contact karein."
        ),
        "broadcast_footer": "\n\n— India Business Wallets",
    }

    for key, value in defaults.items():
        db.execute(
            """
            INSERT OR IGNORE INTO settings
            (setting_key, setting_value)
            VALUES (?, ?)
            """,
            (key, value),
        )

    db.commit()
    db.close()


def get_setting(key, default=""):
    db = open_database()
    row = db.execute(
        "SELECT setting_value FROM settings WHERE setting_key = ?",
        (key,),
    ).fetchone()
    db.close()
    return row["setting_value"] if row else default


def update_setting(key, value):
    db = open_database()
    db.execute(
        """
        INSERT INTO settings (setting_key, setting_value)
        VALUES (?, ?)
        ON CONFLICT(setting_key)
        DO UPDATE SET setting_value = excluded.setting_value
        """,
        (key, value),
    )
    db.commit()
    db.close()


def save_bot_user(user, action):
    if not user:
        return

    db = open_database()

    existing = db.execute(
        "SELECT telegram_id FROM bot_users WHERE telegram_id = ?",
        (user.id,),
    ).fetchone()

    if existing:
        db.execute(
            """
            UPDATE bot_users
            SET first_name = ?,
                username = ?,
                last_action = ?,
                updated_at = ?
            WHERE telegram_id = ?
            """,
            (
                user.first_name or "User",
                user.username or "",
                action,
                now_text(),
                user.id,
            ),
        )
    else:
        db.execute(
            """
            INSERT INTO bot_users
            (
                telegram_id,
                first_name,
                username,
                last_action,
                joined_at,
                updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                user.id,
                user.first_name or "User",
                user.username or "",
                action,
                now_text(),
                now_text(),
            ),
        )

    db.commit()
    db.close()


def save_conversation(telegram_id, sender_type, message_text):
    db = open_database()
    db.execute("INSERT INTO conversations (telegram_id,sender_type,message_text,is_read,created_at) VALUES (?,?,?,?,?)", (telegram_id, sender_type, message_text, 0 if sender_type == "user" else 1, now_text()))
    db.commit()
    db.close()


def add_log(action):
    db = open_database()
    db.execute(
        """
        INSERT INTO activity_logs
        (admin_username, action, created_at)
        VALUES (?, ?, ?)
        """,
        (
            session.get("admin_username", "system"),
            action,
            now_text(),
        ),
    )
    db.commit()
    db.close()


def create_application(user, service_type):
    db = open_database()

    cursor = db.execute(
        """
        INSERT INTO applications
        (
            telegram_id,
            customer_name,
            telegram_username,
            service_type,
            status,
            created_at,
            updated_at
        )
        VALUES (?, ?, ?, ?, 'Pending', ?, ?)
        """,
        (
            user.id,
            user.first_name or "User",
            user.username or "",
            service_type,
            now_text(),
            now_text(),
        ),
    )

    row_id = cursor.lastrowid
    application_code = (
        f"IBW-{datetime.now().strftime('%y%m')}-{row_id:05d}"
    )

    db.execute(
        """
        UPDATE applications
        SET application_code = ?
        WHERE id = ?
        """,
        (application_code, row_id),
    )

    db.commit()
    db.close()

    return row_id, application_code


