# =========================================================
# SAFE MESSAGE REPLACEMENT
# =========================================================

async def replace_query_message(query, text, reply_markup=None):
    """
    Photo messages contain captions, not normal text.
    For a photo welcome message, remove it and send a new text message.
    For a normal text message, edit it normally.
    """
    if query.message.photo:
        try:
            await query.message.delete()
        except Exception:
            pass

        await query.message.chat.send_message(
            text=text,
            reply_markup=reply_markup,
        )
    else:
        await query.edit_message_text(
            text=text,
            reply_markup=reply_markup,
        )


