async def send_welcome(update: Update):
    user = update.effective_user
    save_bot_user(user, "Opened main menu")

    name = user.first_name if user and user.first_name else "User"
    title = get_setting(
        "welcome_title",
        "Welcome to India Business Wallets",
    )

    caption = (
        f"👋 Hello {name}!\n\n"
        f"🎉 {title}\n\n"
        "💳 Google Pay Business\n"
        "🏪 BharatPe Business\n"
        "📝 Apply Now & Track Status\n\n"
        "Neeche diye gaye button se service select karein 👇"
    )

    image_path = ensure_welcome_image()

    try:
        with image_path.open("rb") as photo:
            await update.effective_message.reply_photo(
                photo=photo,
                caption=caption,
                reply_markup=main_menu_keyboard(),
            )
    except Exception as error:
        print("Welcome image error:", error)

        await update.effective_message.reply_text(
            caption,
            reply_markup=main_menu_keyboard(),
        )


