panel = Flask(__name__)
panel.secret_key = os.getenv("PANEL_SECRET_KEY", secrets.token_hex(32))


def get_panel_db():
    if "db" not in g:
        g.db = open_database()
    return g.db


@panel.teardown_appcontext
def close_panel_db(error=None):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def login_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if "admin_id" not in session:
            return redirect(url_for("admin_login"))
        return view(*args, **kwargs)

    return wrapped


