def flash_html():
    output = []

    for category, message in get_flashed_messages(
        with_categories=True
    ):
        css = "success" if category == "success" else "danger"
        output.append(
            f'<div class="alert {css}">{html.escape(message)}</div>'
        )

    return "".join(output)


