@panel.route("/broadcast", methods=["GET", "POST"])
@login_required
def broadcast_page():
    result = ""

    if request.method == "POST":
        message_text = request.form.get(
            "message",
            "",
        ).strip()

        if not message_text:
            flash("Message required.", "danger")

        elif not telegram_app:
            flash("Bot is not running.", "danger")

        else:
            users = get_panel_db().execute(
                "SELECT telegram_id FROM bot_users"
            ).fetchall()

            footer = get_setting("broadcast_footer", "")
            complete_message = message_text + footer

            async def send_all():
                sent = 0
                failed = 0

                for user in users:
                    try:
                        await telegram_app.bot.send_message(
                            chat_id=user["telegram_id"],
                            text=complete_message,
                        )
                        sent += 1
                    except Exception:
                        failed += 1

                return sent, failed

            future = run_coroutine(send_all())

            if future:
                try:
                    sent, failed = future.result(timeout=120)

                    result = (
                        "<div class='card'>"
                        f"<b>Sent:</b> {sent} &nbsp; "
                        f"<b>Failed:</b> {failed}"
                        "</div>"
                    )

                    add_log(
                        f"Broadcast sent: {sent}, failed: {failed}"
                    )
                except Exception as error:
                    flash(
                        f"Broadcast error: {error}",
                        "danger",
                    )

    body = f"""
    {result}

    <div class="card" style="max-width:760px">
        <form method="post">
            <label>Broadcast Message</label>

            <textarea name="message"
                      rows="8"
                      placeholder="Sabhi bot users ko message"
                      required></textarea>

            <button type="submit">
                Send Broadcast
            </button>
        </form>
    </div>
    """

    return admin_page("Broadcast", body)


