@panel.route("/chats/<int:telegram_id>", methods=["GET", "POST"])
@login_required
def chat_detail(telegram_id):
    db = get_panel_db()
    user = db.execute("SELECT * FROM bot_users WHERE telegram_id=?", (telegram_id,)).fetchone()
    if not user:
        flash("User nahi mila.", "danger")
        return redirect(url_for("chats_page"))
    if request.method == "POST":
        message = request.form.get("message", "").strip()
        if message:
            future = run_coroutine(telegram_app.bot.send_message(chat_id=telegram_id, text=message)) if telegram_app else None
            try:
                if not future:
                    raise RuntimeError("Bot connected nahi hai")
                future.result(timeout=30)
                save_conversation(telegram_id, "admin", message)
                flash("Reply sent.", "success")
                return redirect(url_for("chat_detail", telegram_id=telegram_id))
            except Exception as error:
                flash(f"Send failed: {error}", "danger")
    db.execute("UPDATE conversations SET is_read=1 WHERE telegram_id=? AND sender_type='user'", (telegram_id,))
    db.commit()
    messages = db.execute("SELECT * FROM conversations WHERE telegram_id=? ORDER BY id", (telegram_id,)).fetchall()
    bubbles = ""
    for m in messages:
        align = "margin-left:auto;background:#dbeafe" if m['sender_type']=='admin' else "margin-right:auto;background:#f3f4f6"
        bubbles += f'''<div style="max-width:75%;{align};padding:12px;border-radius:14px;margin:8px 0"><b>{'Admin' if m['sender_type']=='admin' else html.escape(user['first_name'] or 'User')}</b><br>{html.escape(m['message_text']).replace(chr(10),'<br>')}<div style="font-size:11px;color:#6b7280">{m['created_at']}</div></div>'''
    body = f'''<div class="card"><h2>{html.escape(user['first_name'] or 'User')} <small>@{html.escape(user['username'] or '-')}</small></h2>{bubbles or 'No messages.'}<hr><form method="post"><label>Reply from Admin Panel</label><textarea name="message" rows="4" required></textarea><button class="btn-success">Send Reply</button></form></div>'''
    return admin_page("Direct User Chat", body)


